-- 会话 A（RR）
BEGIN;
SELECT * FROM account WHERE id BETWEEN 1 AND 10;          -- 快照读，生成 ReadView

-- 会话 B
INSERT INTO account(id, balance) VALUES (5, 100); COMMIT;

-- 会话 A
SELECT * FROM account WHERE id BETWEEN 1 AND 10;          -- 仍看不到 id=5（MVCC）
SELECT * FROM account WHERE id BETWEEN 1 AND 10 FOR UPDATE; -- 当前读，能看到 id=5，并加临键锁
COMMIT;

CREATE TABLE t_order (
  id BIGINT PRIMARY KEY, user_id BIGINT, phone VARCHAR(20), status TINYINT,
  create_time DATETIME,
  KEY idx_phone (phone),
  KEY idx_user_status_time (user_id, status, create_time)
);

-- ❌ 隐式转换：phone 是 varchar，参数是数字
EXPLAIN SELECT * FROM t_order WHERE phone = 13800000000;      -- type=ALL
-- ✅
EXPLAIN SELECT * FROM t_order WHERE phone = '13800000000';    -- type=ref

-- ❌ 函数作用在列上
EXPLAIN SELECT * FROM t_order WHERE DATE(create_time) = '2026-10-01';
-- ✅ 改成范围
EXPLAIN SELECT * FROM t_order
 WHERE create_time >= '2026-10-01' AND create_time < '2026-10-02';

-- ❌ 跳过最左列
EXPLAIN SELECT * FROM t_order WHERE status = 1;
-- ✅ 最左前缀
EXPLAIN SELECT * FROM t_order WHERE user_id = 42 AND status = 1;

CREATE TABLE t_user (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(50), age INT, city VARCHAR(50),
  KEY idx_name_age (name, age)
);

-- 回表：二级索引找到 id，再回聚簇索引取 city
EXPLAIN SELECT * FROM t_user WHERE name = '张三';
-- 覆盖索引：name, age, id 都在 idx_name_age 中，Extra: Using index
EXPLAIN SELECT id, name, age FROM t_user WHERE name = '张三';

-- 深分页优化：先用覆盖索引查 id，再关联回表
SELECT u.* FROM t_user u
JOIN (SELECT id FROM t_user ORDER BY id LIMIT 1000000, 20) t ON u.id = t.id;

-- 查看与设置隔离级别（MySQL 8.0）
SELECT @@transaction_isolation;
SET SESSION TRANSACTION ISOLATION LEVEL READ COMMITTED;

-- 不可重复读演示（RC 下）
-- 会话 A
BEGIN;
SELECT balance FROM account WHERE id = 1;   -- 100
-- 会话 B
UPDATE account SET balance = 200 WHERE id = 1; COMMIT;
-- 会话 A
SELECT balance FROM account WHERE id = 1;   -- RC：200（不可重复读）；RR：仍为 100
COMMIT;

-- 1. 函数 → 范围
-- ❌ WHERE YEAR(create_time) = 2026
SELECT id FROM t_order WHERE create_time >= '2026-01-01' AND create_time < '2027-01-01';

-- 2. 函数索引（MySQL 8.0.13+）
ALTER TABLE t_user ADD INDEX idx_lower_email ((LOWER(email)));
SELECT * FROM t_user WHERE LOWER(email) = 'a@b.com';

-- 3. 统计信息过期导致选错索引
ANALYZE TABLE t_order;
EXPLAIN SELECT * FROM t_order WHERE user_id = 42 AND status = 1;

-- 4. 前导模糊 → 全文索引或搜索引擎
ALTER TABLE t_article ADD FULLTEXT INDEX ft_title (title) WITH PARSER ngram;
SELECT * FROM t_article WHERE MATCH(title) AGAINST('面试' IN BOOLEAN MODE);

-- 1. 深度分页：LIMIT 1000000, 20 扫描 100 万行后丢弃
SELECT * FROM t_order WHERE user_id = 1 ORDER BY id LIMIT 1000000, 20;
-- 改为游标分页
SELECT * FROM t_order WHERE user_id = 1 AND id > #{lastId} ORDER BY id LIMIT 20;
-- 2. 索引失效：对列使用函数
SELECT * FROM t_order WHERE DATE(created_at) = '2026-10-31';
-- 改为范围
SELECT * FROM t_order WHERE created_at >= '2026-10-31' AND created_at < '2026-11-01';
-- 3. 隐式转换：phone 为 varchar 却传入数字 -> 索引失效
SELECT * FROM t_user WHERE phone = '13800000000';

-- 事务 A                                  -- 事务 B
BEGIN;                                     BEGIN;
UPDATE account SET bal=bal-10 WHERE id=1;  UPDATE account SET bal=bal-10 WHERE id=2;
UPDATE account SET bal=bal+10 WHERE id=2;  UPDATE account SET bal=bal+10 WHERE id=1;
-- 等待 B 持有的 id=2                       -- 等待 A 持有的 id=1 -> 死锁，一个事务被回滚

-- 修复：按 id 顺序加锁
SELECT * FROM account WHERE id IN (1, 2) ORDER BY id FOR UPDATE;
SHOW ENGINE INNODB STATUS\G   -- LATEST DETECTED DEADLOCK

CREATE INDEX idx_user_status_time ON t_order(user_id, status, created_at);

-- 可以使用索引（且覆盖，无回表）
SELECT id, status, created_at FROM t_order WHERE user_id = 1 AND status = 'PAID';
-- 利用索引顺序排序，无 filesort
SELECT id FROM t_order WHERE user_id = 1 AND status = 'PAID' ORDER BY created_at DESC LIMIT 20;
-- 只能用到 user_id
SELECT * FROM t_order WHERE user_id = 1 AND created_at > '2026-10-01';
-- 无法使用（缺少最左列）
SELECT * FROM t_order WHERE status = 'PAID';

CREATE TABLE t_order (
  id BIGINT PRIMARY KEY,
  user_id BIGINT, status TINYINT, amount DECIMAL(10,2),
  create_time DATETIME, remark VARCHAR(500),
  KEY idx_user_time (user_id, create_time)
);

-- 回表：remark、amount 不在索引中
EXPLAIN SELECT * FROM t_order WHERE user_id = 42 ORDER BY create_time DESC LIMIT 10;
-- Extra: Using where   （每条记录要回表取整行）

-- 覆盖索引：只查索引中有的列（二级索引叶子包含主键 id）
EXPLAIN SELECT id, user_id, create_time FROM t_order WHERE user_id = 42;
-- Extra: Using index   （无回表）

-- 延迟关联：深分页先在索引上找到 10 个主键，再回表
SELECT o.* FROM t_order o
JOIN (SELECT id FROM t_order WHERE user_id = 42
      ORDER BY create_time DESC LIMIT 100000, 10) t ON o.id = t.id;

CREATE TABLE t_user (
  id BIGINT PRIMARY KEY,
  name VARCHAR(50),
  phone VARCHAR(20) NULL,
  status TINYINT,
  KEY idx_status (status)
);
-- 数据：3 行，其中 1 行 phone 为 NULL

SELECT COUNT(*)      FROM t_user;   -- 3  行数
SELECT COUNT(1)      FROM t_user;   -- 3  与 COUNT(*) 等价
SELECT COUNT(phone)  FROM t_user;   -- 2  忽略 NULL
SELECT COUNT(DISTINCT status) FROM t_user;

EXPLAIN SELECT COUNT(*) FROM t_user;
-- key = idx_status   优化器选了更小的二级索引，而不是主键

