# ShardingSphere：订单按 user_id 分 4 库 16 表
t_order:
  actualDataNodes: ds_${0..3}.t_order_${0..15}
  databaseStrategy:
    standard: { shardingColumn: user_id, shardingAlgorithmName: db_mod }
  tableStrategy:
    standard: { shardingColumn: user_id, shardingAlgorithmName: tb_mod }
  keyGenerateStrategy: { column: order_id, keyGeneratorName: snowflake }

// 写后读走主库：ShardingSphere / 自定义数据源路由
public OrderVO createAndGet(CreateCmd cmd) {
    long id = orderService.create(cmd);
    try (HintManager hint = HintManager.getInstance()) {
        hint.setWriteRouteOnly();          // 本次查询强制主库
        return orderService.detail(id);
    }
}
